effect.shader:
#define PI 3.1415926536

vec4 preMultiplicada(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// A volta da `acCamadaParaTela`: UV da tela → UV do buffer da camada.
vec2 naCamada(vec2 t) {
    vec3 c = inverse(acCamadaParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

// A função do AM, linha por linha.
float rays(vec2 st, float pixelSize, float feather, float width, float count, float innerRadius, float outerRadius,
           float radialFeather, float bendStrength, float bendFrequency, float bendPhase, float angle) {
    float r = length(st);
    float theta = (atan(st.x, st.y) + angle) / (2.0 * PI);
    theta += sin(r * bendFrequency + bendPhase) * bendStrength;
    float sweep = 1. / count;
    float t = mod(theta, sweep) / sweep;
    float h = feather / 2. * pixelSize / r;
    float halfWidth = width / 2.;
    float low = smoothstep(0.5 - halfWidth - h, 0.5 - halfWidth + h, t);
    float high = smoothstep(0.5 + halfWidth + h, 0.5 + halfWidth - h, t);
    float rf = radialFeather / 2. * pixelSize;
    float inside = smoothstep(innerRadius - rf, innerRadius + rf, r);
    float outside = smoothstep(outerRadius + rf, outerRadius - rf, r);
    return low * high * inside * outside;
}

void main() {
    vec4 texColor = preMultiplicada(texture(inputImg, acScreenNorm));

    // O `acLayerNorm` do AM: o retângulo do conteúdo de 0 a 1, com o Y para CIMA (a matriz dele inverte o Y da tela;
    // o buffer de camada do Nova cresce para baixo). A mesma ponte do Túnel (AM).
    vec2 conteudo = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 st = 0.5 + (naCamada(acTela(acScreenNorm)) - 0.5) * acTamanhoDaTela / conteudo;
    st.y = 1.0 - st.y;

    // Daqui em diante, o `main` do AM.
    st.y = 1. - st.y;
    st -= 0.5;
    st.x *= conteudo.x / conteudo.y;
    float pixelSize = 1. / length(acTamanhoDaTela);

    float p = rays(st - position / 1000.0, pixelSize, feather, rayWidth, pointCount, innerRadius, outerRadius,
                   radialFeather, bendStrength / 10., bendFrequency, bendPhase, angle / 57.2958);

    vec4 adjColor = vec4(color.rgb, 1.0) * p;

    vec4 result;
    if (texColor.a <= 0.0) {
        // Lá, 0 ÷ 0 = NaN nos dois modos que dividem pelo alfa, e o pixel sai vazio; no Normal, a camada (vazia).
        result = vec4(0.0);
    } else if (blendMode == 1) {
        result = vec4((texColor.rgb / texColor.a) * adjColor.rgb, 1.0) * texColor.a;
    } else if (blendMode == 2) {
        result = vec4(1. - ((1. - (texColor.rgb / texColor.a)) * (1. - adjColor.rgb)), 1.0) * texColor.a;
    } else {
        result = adjColor * texColor.a;
        result = texColor * (1. - result.a) + result;
    }
    vec4 c = mix(texColor, result, alpha);
    fragColor = c.a > 0.0 ? vec4(min(c.rgb / c.a, vec3(1.0)), c.a) : vec4(0.0);
}
